/**
 * Worker entry: the OpenNext-generated handler for every request, plus a
 * nightly cron (see "triggers" in wrangler.jsonc) that resets the demo data.
 */
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { resetDemoData } from "./src/db/reset";

export default {
  fetch: handler.fetch,
  async scheduled(_controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    if (env.DEMO_MODE !== "true") return;
    ctx.waitUntil(resetDemoData(env.DB).then((n) => console.log(`demo reset: ${n} statements`)));
  },
} satisfies ExportedHandler<CloudflareEnv>;
